import sqlite3

def apply_discount(total, customer_type, coupon=None):
    """Return the price after discounts. Regular customers get 5 %, premium 10 %.
    A coupon like "SAVE20" takes a further 20 % off, but the price must never drop below 0."""
    if customer_type == "premium":
        total = total * 0.9
    elif customer_type == "regular":
        total = total * 0.95
    if coupon:
        percent = int(coupon[4:])
        total = total - total * percent / 100
    return round(total, 1)

def average_order_value(orders):
    return sum(o["total"] for o in orders) / len(orders)

def find_orders(db_path, customer_name):
    conn = sqlite3.connect(db_path)
    query = f"SELECT id, total FROM orders WHERE customer = '{customer_name}'"
    rows = conn.execute(query).fetchall()
    return rows
